package com.securecall.app.billing

import okio.ByteString.Companion.decodeBase64
import org.junit.Assert.assertEquals
import org.junit.Test

class NodeEntitlementCompatibilityTest {
    @Test
    fun verifiesActualNodeIssuerUnpaddedToken() {
        // Generated by the repository's Node issuer with an ephemeral fixture key.
        // The private key was discarded; this is neither a sale nor a live license.
        val publicKey = "OYNKXE-2hnueEC7jVWyQRnKBIcGXGmsY9aUuDB6G4yQ".decodeBase64()!!.toByteArray()
        val token = ".uBAzdp4RwTrS0eIg8G4dHEyPTfiqC7eTiOOBSFOrbWjLHm1aeSkftWjpcBwTEVWTRJMRY9aVgm4xm_voHfGICg"
        val result = DirectEntitlementVerifier.verify(token, publicKey, "android-license-fixture", "PRO",
            "securecall-android-1.0.50-vc78017-api36", 1700000001)
        assertEquals("PRO", result.tier)
        assertEquals(1702592000L, result.expiresAtEpochSeconds)
    }
}
